import{_ as r,l as n,o as e,c as i,v as t,p as l,x as o,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"TEE：SGX / TrustZone","description":"","frontmatter":{"title":"TEE：SGX / TrustZone","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tee-sgx-trustzone.md","filePath":"cs/tee-sgx-trustzone.md","lastUpdated":1789023840000}'),p={name:"cs/tee-sgx-trustzone.md"};function u(c,a,T,S,_,m){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="tee-sgx-trustzone" tabindex="-1">TEE：SGX / TrustZone <a class="header-anchor" href="#tee-sgx-trustzone" aria-label="Permalink to &quot;TEE：SGX / TrustZone&quot;">​</a></h1><div class="epigraph"><p>可信执行环境把敏感代码放进与操作系统隔离的飞地。SGX 在进程内划飞地，TrustZone 划安全世界。TCB 变小，但侧信道、接口与供应仍在模型里。</p><footer>—— Costan and Devadas, Intel SGX Explained；ARM TrustZone 白皮书；对照[隔离](/cs/isolation-sandbox)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/windows-kerberos-attacks">Kerberos</a>的密钥仍可能在 OS 内存。缺口是<strong>对 OS 也不信任时</strong>的盒子。本课对照 SGX 与 TrustZone，不写飞地攻击步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HSM 是外盒；TEE 是 CPU 里的盒。飞地密封、远程证明（后课）。缺口是：OS 仍调度与供页，侧信道模型要打开。</p><h3 id="接口" tabindex="-1">接口 <a class="header-anchor" href="#接口" aria-label="Permalink to &quot;接口&quot;">​</a></h3><p>飞地与不可信世界的调用约定是新攻击面，要当协议审。</p><p><span class="marginnote">Costan–Devadas。SGX 的公开研究含侧信道，本课不复现。机密计算下一课把 TEE 收到云产品叙事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：TrustZone 安全世界 vs SGX 用户态飞地。指出内存加密引擎的角色。下一课机密计算。</p>',12)),(e(),l(h,null,{default:o(()=>[E(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OS%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%20OS%22%5D%20--%3E%20EE%5B%22%E9%A3%9E%E5%9C%B0%E6%88%96%E5%AE%89%E5%85%A8%E4%B8%96%E7%95%8C%22%5D%0A%20%20EE%20--%3E%20SEAL%5B%22%E5%AF%86%E5%B0%81%E5%AF%86%E9%92%A5%22%5D%0A%20%20OS%20-.-%3E%7C%22%E4%BE%A7%E4%BF%A1%E9%81%93%E4%B8%8E%E6%8E%A5%E5%8F%A3%22%7C%20EE%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缩小对 OS 的信任。证明下一课让远端相信飞地度量。机密计算把同一思想卖给云租户。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写飞地利用。机密计算下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>票据密钥怕 OS；TEE 对 OS 隔离敏感码。</li><li>SGX 飞地，TrustZone 安全世界。</li><li>侧信道与调用约定仍在模型里。</li><li>下一课机密计算。</li><li>出处：Costan and Devadas；ARM TrustZone；<a href="/cs/isolation-sandbox">isolation-sandbox</a>。</li></ul>',8))])}const f=r(p,[["render",u]]);export{x as __pageData,f as default};
